-- 017: SIP credentials for extension provisioning
-- The secret is generated by CloudTel and pushed to the PBX. It is returned
-- only to the authenticated owner of the extension via /settings/telephony so
-- the browser can complete SIP digest authentication over WSS.
ALTER TABLE extensions
  ADD COLUMN IF NOT EXISTS sip_password text NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS sip_password_updated_at timestamptz;

CREATE INDEX IF NOT EXISTS idx_extensions_provision_needed
  ON extensions (organisation_id)
  WHERE status = 'active' AND (sip_password = '' OR pbx_endpoint_id IS NULL);
